/* ===== src/js/41-dock.js ===== */
/* ==========================================================================
   Dock: one row at every size
   --------------------------------------------------------------------------
   A dock never wraps: two rows of destinations read as a grid of buttons, not as the app's
   main places. This script picks the richest presentation that fits on ONE row and writes
   it to data-fit; dock.css draws each one:

     labels    every destination shows its icon and its word (the default)
     compact   the current destination shows its word; the others show the icon only
     icons     every destination shows the icon only; the current one is the filled circle

   The measuring is SG.fit (05-fit.js). It re-checks when the dock's size changes (a rotation,
   the reader's text size, a font loading), when a dock is added, and when the current
   destination changes (its word is the widest thing in the compact row). The words stay in
   the DOM in every presentation, as the accessible names. data-compact on the dock starts at
   compact. Without JS the dock keeps its words and wraps onto a second row (the CSS fallback).

   API   SG.dock.fit()   re-check every dock now
   ========================================================================== */
(function (SG) {
  'use strict';

  SG.fit.register('.dock', {
    steps: ['labels', 'compact', 'icons'],
    measure: '.dock__list', /* the list holds one row (the CSS sets nowrap once data-fit exists) */
    start: function (dock) { return dock.hasAttribute('data-compact') ? 1 : 0; },
    attrs: ['aria-current', 'data-compact']
  });

  SG.dock = { fit: SG.fit.update };
})((window.SG = window.SG || {}));
